      const target = resolveAgentProposal(body.proposal || "", {
        mutation: Boolean(hostedSharedProvider),
        expectedHead: body.expectedProposalHead,
      });
      if (target.projectId !== agent.projectId) throw sharedRequestError("The proposal belongs to another project", 403, "agent_project_scope_denied");
      const push = await requestSharedPublicationPush(connection.repository);
      const proposal = target.root ? target : openSharedProposalWorkspace(root, {
        proposal: target.branch,
        ...(hostedSharedProvider ? { expectedHead: target.head } : {}),
        ...(push ? { push, timeoutMs: push.timeoutMs } : {}),
      });
